import{_ as o,c as a,a as i,o as c}from"./app-C_dHcy8Q.js";const t={};function r(l,e){return c(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="security" tabindex="-1"><a class="header-anchor" href="#security"><span>Security</span></a></h1><ul><li>mTLS for Server/Agent</li><li>OIDC/MFA for users</li><li>RBAC/ABAC, approvals, audit log chain</li></ul><p>Approvals (Two-person rule)</p><ul><li>Enable: set <code>auth.two_person_rule: true</code> in function descriptor; HTTP 提交将返回 <code>202</code> 和 <code>approval_id</code>。</li><li>Storage: <ul><li>Memory: 默认（不提供 DATABASE_URL）</li><li>PostgreSQL: 设置 <code>DATABASE_URL=postgres://...</code>，二进制以 <code>-tags pg</code> 构建；表结构参见 <code>database/schema.sql</code> 中 <code>approvals</code>。</li><li>SQLite (可选): 设置 <code>DATABASE_URL=sqlite:///path/to/croupier.db</code> 或 <code>file:/path/to/croupier.db</code>，二进制以 <code>-tags sqlite</code> 构建；首次启动会自动建表。</li></ul></li><li>API： <ul><li>列表：<code>GET /api/approvals?state=pending&amp;function_id=&amp;game_id=&amp;env=&amp;actor=&amp;mode=&amp;page=1&amp;size=20&amp;sort=created_at_desc</code><ul><li>返回：<code>{ approvals: [...], total, page, size }</code></li></ul></li><li>详情：<code>GET /api/approvals/get?id=...</code>（含 <code>payload_preview</code> 脱敏快照）</li><li>同意：<code>POST /api/approvals/approve</code>，body <code>{ &quot;id&quot;: &quot;...&quot; }</code>（同意后立即执行原调用并返回结果/Job）</li><li>拒绝：<code>POST /api/approvals/reject</code>，body <code>{ &quot;id&quot;: &quot;...&quot;, &quot;reason&quot;: &quot;...&quot; }</code></li></ul></li><li>审计：<code>approval_approve</code>/<code>approval_reject</code> 事件记录在审计链中；调用审计包含 <code>trace_id</code> 与脱敏快照。</li></ul><p>Notes</p><ul><li>UI 审批页已提供（/gm/approvals）：待办列表（分页/筛选）→ 详情侧栏 → 同意/拒绝；对高危函数已支持二次确认与 MFA（OTP）。</li><li>生产建议：优先 PostgreSQL，并为 approvals 表添加备份策略与告警（待办积压/拒绝率异常）。SQLite 适用于单机/PoC/嵌入式部署。</li></ul><p>RBAC/ABAC</p><ul><li>RBAC：基于角色/用户的 permission 检查，支持 game 作用域（<code>game:&lt;game_id&gt;:permission</code>）。</li><li>ABAC（简易表达式）：在函数描述 <code>auth.allow_if</code> 中配置表达式（==、!=、&amp;&amp;、||、has_role(&#39;admin&#39;)） <ul><li>可用变量：<code>user</code>、<code>game_id</code>、<code>env</code>、<code>function_id</code></li><li>示例：<code>env == &quot;prod&quot; &amp;&amp; has_role(&#39;admin&#39;)</code></li></ul></li></ul><p>Rate limit &amp; Concurrency</p><ul><li>在函数描述 <code>semantics.rate_limit</code>（例如 <code>10rps</code>）与 <code>semantics.concurrency</code>（整数）启用限流/并发限制。</li><li>触达限制时返回 HTTP 429。</li></ul>',10)])])}const s=o(t,[["render",r]]),p=JSON.parse('{"path":"/security.html","title":"Security","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1762002341000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":4,"url":"https://github.com/cuihairu"}],"changelog":[{"hash":"228147054e4f1a15cada6bb3a8af42c4128040fb","time":1762002341000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"chore: commit local changes"},{"hash":"d23b283e871df1362d50a3dabf5bd4e8d8d10ef1","time":1761968750000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"server(http): approvals persistence (Postgres via -tags pg, fallback memory) + pagination/filter/detail APIs; start_job transport encode; audit masking; pack extract; docs &#x26; schema."},{"hash":"2850102635c30770039d04ddc769f91e4129703e","time":1761962609000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"docs: rename Core concept to Server across README and docs"},{"hash":"8e304eb04907065b7a86a2e28431a17d03e2e4e2","time":1761174667000,"email":"chuihairu@gmail.com","author":"cuihairu","message":"feat(core,agent,ui): introduce gRPC+mTLS vNext skeleton with Core↔Agent↔SDK E2E, HTTP API, dynamic UI, jobs and RBAC\\\\n\\\\n- Protocol/IDL: add Function/Control proto (with dev stubs); buf configs\\\\n- Core: gRPC server, ControlService, FunctionService routing, HTTP API (/api/descriptors,/api/invoke,/api/start_job,/api/stream_job,/api/cancel_job)\\\\n- Agent: local FunctionService routing, LocalControlService for SDK registration, job executor with idempotency + cancel\\\\n- SDK: local handler hosting, schema validation, idempotency helper; example game server\\\\n- UI: static page with descriptor-driven form, invoke + start job + cancel, SSE progress\\\\n- Security: mTLS wiring, audit chain logger, basic RBAC (policy loader, HTTP enforcement)\\\\n- Tooling: Makefile, dev cert script, CI workflow, docs skeleton and descriptors"}]},"filePathRelative":"security.md"}');export{s as comp,p as data};
